+		case transcript.TypeAssistant:
+			var blocks []compactAssistantBlock
+			if err := json.Unmarshal(line.Content, &blocks); err != nil {
+				continue
+			}
+			for _, block := range blocks {
+				switch block.Type {
+				case transcript.ContentTypeText:
+					if block.Text != "" {
+						entries = append(entries, Entry{
